UsbWrapperCodeUpdater::UsbWrapperCodeUpdater(USBD_NODE_ID usbNodeId,
		UINT16 usbDeviceType, EvolWrapperCommManager * pWrapCom) : IUsbCodeUpdater(usbNodeId, usbDeviceType), responseCounter_(0),
		popedPrepareToFlashMsg_(false), masterAppOnly_(false), allAppsMasterDataBoot_(false)
{
	pMyWrapperComm_ = pWrapCom;
	pCommMgr_ = 0;

	responseStateMachine_ = waitingForNewInstalledSrc;

	//UPDATER_SYNC
	PAL_absclass::PAL_releaseMutex(update_lock);

#if defined ( __linux__ )
	Debug::trace("UsbWrapperCodeUpdater", HobString("Constructor Called nodeId = ") + Integer::toString64((int64_t)usbNodeId) + HobString(" device type = ") + Integer::toString(usbDeviceType));
#else
	Debug::trace("UsbWrapperCodeUpdater", HobString("Constructor Called nodeId = ") + Integer::toString64((__int64)usbNodeId) + HobString(" device type = ") + Integer::toString(usbDeviceType));
#endif
}

UsbWrapperCodeUpdater::~UsbWrapperCodeUpdater()
{
	Debug::trace("UsbWrapperCodeUpdater", HobString("~UsbWrapperCodeUpdater"));

	if (pCommMgr_)
		delete pCommMgr_;
	Debug::trace("UsbWrapperCodeUpdater", HobString("~UsbWrapperCodeUpdater():  Goodbye."));
}

void UsbWrapperCodeUpdater::requestUpdate(EvolWrapperSystemStatus wrSysStatus)
{
	Debug::trace("UsbWrapperCodeUpdater", "requestUpdate():  Begin.");
	responseCounter_ = 0;
	burnList_.clear();
	upgradeList_.clear();
	reqUpgradeList_.clear();
	masterAppOnly_ = false;
	allAppsMasterDataBoot_ = false;

	Util::CLockCriticalSection lock( updateCrit );
	//node 2 (master board)
	processSystemStatusMessageForNode(2, HobVersion::WRMasterAppSW, HobVersion::WRMasterNVDataSW, HobVersion::WRMasterBootSW, wrSysStatus);

	//node 1 
	processSystemStatusMessageForNode(1, HobVersion::WRSlave1AppSW, HobVersion::WRSlave1NVDataSW, HobVersion::WRSlave1BootSW, wrSysStatus);

	//node 3 
	processSystemStatusMessageForNode(3, HobVersion::WRSlave3AppSW, HobVersion::WRSlave3NVDataSW, HobVersion::WRSlave3BootSW, wrSysStatus);

	//node 4 
	processSystemStatusMessageForNode(4, HobVersion::WRSlave4AppSW, HobVersion::WRSlave4NVDataSW, HobVersion::WRSlave4BootSW, wrSysStatus);

	//node 5 
	processSystemStatusMessageForNode(5, HobVersion::WRSlave5AppSW, HobVersion::WRSlave5NVDataSW, HobVersion::WRSlave5BootSW, wrSysStatus);

	//node 6 
	processSystemStatusMessageForNode(6, HobVersion::WRSlave6AppSW, HobVersion::WRSlave6NVDataSW, HobVersion::WRSlave6BootSW, wrSysStatus);
	Debug::trace("UsbWrapperCodeUpdater", "requestUpdate():  Done.");
}

void UsbWrapperCodeUpdater::sendUpdateRequest(int EWSModel)
{
	Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  reqUpgradeList_.size() = " + Integer::toString((int) reqUpgradeList_.size()));
	if(reqUpgradeList_.size() > 0)
	{
		responseStateMachine_ = waitingForResponses;
	
		reqIterator_  = reqUpgradeList_.begin();

		while(reqIterator_ != reqUpgradeList_.end())
		{
			//if model number is EWS, change the components within the requests to EWS and dispatch.
			if (EWSModel == 2)//CLA
			{
				Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  Chose CLA");
				PeripheralRequestCodeUpdate *pReqCodeUpdate = *reqIterator_;
				HobVersion *softVer = (HobVersion *)pReqCodeUpdate->getSoftwareVersion();
				HobVersion::VersionType verType = softVer->getVersionType();

				//change to the EWS equivalent.
				switch(verType)
				{
					case HobVersion::WRMasterNVDataSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  CLADataSW");
						softVer->setVersionType(HobVersion::CLADataSW);
					}
					break;
					case HobVersion::WRMasterBootSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  CLABootSW");
						softVer->setVersionType(HobVersion::CLABootSW);
					}
					break;
					case HobVersion::WRMasterAppSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  CLAAppSW");
						softVer->setVersionType(HobVersion::CLAAppSW);
					}
					break;
					default:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WENT INTO DEFAULT");
					}
				}
			}

			else if (EWSModel == 1)//EWS
			{
				Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  Chose EWS");
				PeripheralRequestCodeUpdate *pReqCodeUpdate = *reqIterator_;
				HobVersion *softVer = (HobVersion *)pReqCodeUpdate->getSoftwareVersion();
				HobVersion::VersionType verType = softVer->getVersionType();

				//change to the EWS equivalent.
				switch(verType)
				{
					case HobVersion::WRMasterNVDataSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WREMasterNVDataSW");
						softVer->setVersionType(HobVersion::WREMasterNVDataSW);
					}
					break;
					case HobVersion::WRMasterBootSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WREMasterBootSW");
						softVer->setVersionType(HobVersion::WREMasterBootSW);
					}
					break;
					case HobVersion::WRMasterAppSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WREMasterAppSW");
						softVer->setVersionType(HobVersion::WREMasterAppSW);
					}
					break;
					case HobVersion::WRSlave1NVDataSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave1NVDataSW");
						softVer->setVersionType(HobVersion::WRESlave1NVDataSW);
					}
					break;
					case HobVersion::WRSlave1BootSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave1BootSW");
						softVer->setVersionType(HobVersion::WRESlave1BootSW);
					}
					break;
					case HobVersion::WRSlave1AppSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave1AppSW");
						softVer->setVersionType(HobVersion::WRESlave1AppSW);
					}
					break;
					case HobVersion::WRSlave3NVDataSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave3NVDataSW");
						softVer->setVersionType(HobVersion::WRESlave3NVDataSW);
					}
					break;
					case HobVersion::WRSlave3BootSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave3BootSW");
						softVer->setVersionType(HobVersion::WRESlave3BootSW);
					}
					break;
					case HobVersion::WRSlave3AppSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave3AppSW");
						softVer->setVersionType(HobVersion::WRESlave3AppSW);
					}
					break;
					case HobVersion::WRSlave4NVDataSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave4NVDataSW");
						softVer->setVersionType(HobVersion::WRESlave4NVDataSW);
					}
					break;
					case HobVersion::WRSlave4BootSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave4BootSW");
						softVer->setVersionType(HobVersion::WRESlave4BootSW);
					}
					break;
					case HobVersion::WRSlave4AppSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave4AppSW");
						softVer->setVersionType(HobVersion::WRESlave4AppSW);
					}
					break;
					case HobVersion::WRSlave5NVDataSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave5NVDataSW");
						softVer->setVersionType(HobVersion::WRESlave5NVDataSW);
					}
					break;
					case HobVersion::WRSlave5BootSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave5BootSW");
						softVer->setVersionType(HobVersion::WRESlave5BootSW);
					}
					break;
					case HobVersion::WRSlave5AppSW:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  WRESlave5AppSW");
						softVer->setVersionType(HobVersion::WRESlave5AppSW);
					}
					break;
					default:
					{
						Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  verType = " + Integer::toString(verType));
					}
				}
			}
			dispatchEvent(*reqIterator_);
			reqIterator_++;
		}
	}
	Debug::trace("UsbWrapperCodeUpdater", "sendUpdateRequest():  Done.");
}

void UsbWrapperCodeUpdater::processSystemStatusMessageForNode(int nodeNumber,
		HobVersion::VersionType appSoftwareType,
		HobVersion::VersionType dataSoftwareType,
		HobVersion::VersionType bootSoftwareType,
		EvolWrapperSystemStatus &wrSysStatus)
{
	HobString msgDebug = "processSystemStatusMessageForNode(" + Integer::toString(nodeNumber) + "):  ";
	int i;

	//find the correct index for the node we are to process.
	for (i = 0; (i < MAX_NODES) && wrSysStatus.getNode(i).getNodeId() != nodeNumber; i++);

	if (i != MAX_NODES)
	{
		Debug::trace("UsbWrapperCodeUpdater", msgDebug + "masterAppOnly_ = " + Bool::toString(masterAppOnly_) + ",  allAppsMasterDataBoot_ = " + Bool::toString(allAppsMasterDataBoot_));
		//	If Node 2 is not a Manufacturing image, we can include the other nodes and components.
		if (!masterAppOnly_)
		{
			HobVersion hardwareVersion;
			HobVersion wrapperSoftwareVersion;

			hardwareVersion.setVersionType(HobVersion::WrapperControllerHW);
			hardwareVersion.setMajorRevision(1);
			hardwareVersion.setMinorRevision(0);
    	    responseCounter_ += 1;

            Debug::trace("UsbWrapperCodeUpdater", msgDebug + "responseCounter_ = " + Integer::toString(responseCounter_));

			wrapperSoftwareVersion.setVersionType(appSoftwareType);
			wrapperSoftwareVersion.setMajorRevision(wrSysStatus.getNode(i).getAppFlash().getMajorRevision());
			wrapperSoftwareVersion.setMinorRevision(wrSysStatus.getNode(i).getAppFlash().getMinorRevision());
			if ((nodeNumber == 2) && (wrapperSoftwareVersion.getMajorRevision() == 0) && (wrapperSoftwareVersion.getMinorRevision() == 0))
				masterAppOnly_ = true;
			Debug::trace("UsbWrapperCodeUpdater", msgDebug + "App wrapperSoftwareVersion = " + Integer::toString(wrapperSoftwareVersion.getMajorRevision()) + "." + Integer::toString(wrapperSoftwareVersion.getMinorRevision()) + ",  masterAppOnly_ = " + Bool::toString(masterAppOnly_));

			if (!masterAppOnly_ || (masterAppOnly_ && (nodeNumber == 2)))
			{
				//	If we have a Manufacturing image on Node 2, only the Application will be downloaded first. Then the wrapper will need to be reset.

				PeripheralRequestCodeUpdate *pReqPrnCodeUpdate_A = new PeripheralRequestCodeUpdate(usbNodeId_, hardwareVersion, wrapperSoftwareVersion);			
				reqUpgradeList_.push_back(pReqPrnCodeUpdate_A);
			}

			if (!masterAppOnly_)
			{
				wrapperSoftwareVersion.setVersionType(dataSoftwareType);
				wrapperSoftwareVersion.setMajorRevision(wrSysStatus.getNode(i).getDataFlash().getMajorRevision());
				wrapperSoftwareVersion.setMinorRevision(wrSysStatus.getNode(i).getDataFlash().getMinorRevision());
				if ((nodeNumber == 2) && (wrapperSoftwareVersion.getMajorRevision() == 0) && (wrapperSoftwareVersion.getMinorRevision() == 0))
					allAppsMasterDataBoot_ = true;
				Debug::trace("UsbWrapperCodeUpdater", msgDebug + "Data wrapperSoftwareVersion = " + Integer::toString(wrapperSoftwareVersion.getMajorRevision()) + "." + Integer::toString(wrapperSoftwareVersion.getMinorRevision()));

				if (!allAppsMasterDataBoot_ || (allAppsMasterDataBoot_ && (nodeNumber == 2)))
				{
					//	We can include the other components (Data and Boot).
	    	 		responseCounter_ += 2;

					PeripheralRequestCodeUpdate *pReqPrnCodeUpdate_D = new PeripheralRequestCodeUpdate(usbNodeId_, hardwareVersion, wrapperSoftwareVersion);			
					reqUpgradeList_.push_back(pReqPrnCodeUpdate_D);

					wrapperSoftwareVersion.setVersionType(bootSoftwareType);
					wrapperSoftwareVersion.setMajorRevision(wrSysStatus.getNode(i).getBootFlash().getMajorRevision());
					wrapperSoftwareVersion.setMinorRevision(wrSysStatus.getNode(i).getBootFlash().getMinorRevision());
					Debug::trace("UsbWrapperCodeUpdater", msgDebug + "Boot wrapperSoftwareVersion = " + Integer::toString(wrapperSoftwareVersion.getMajorRevision()) + "." + Integer::toString(wrapperSoftwareVersion.getMinorRevision()));

					PeripheralRequestCodeUpdate *pReqPrnCodeUpdate_B = new PeripheralRequestCodeUpdate(usbNodeId_, hardwareVersion, wrapperSoftwareVersion);			
					reqUpgradeList_.push_back(pReqPrnCodeUpdate_B);
				}
			}
		}
	}
	Debug::trace("UsbWrapperCodeUpdater", msgDebug + "reqUpgradeList_.size() = " + Integer::toString((int) reqUpgradeList_.size()));
}

void UsbWrapperCodeUpdater::handleVersionManagerDevEvent(VersionManagerEvent verManagerEvent, const char *recvBuffer)
{
	bool traceOn = Debug::isTracing("UsbWrapperCodeUpdater");
	HobString msgDebug;

	Util::CLockCriticalSection lock( updateCrit );

	if (traceOn)
		msgDebug = "handleVersionManagerDevEvent(" + Integer::toString(verManagerEvent) + "):  ";

	switch (verManagerEvent)
	{
		case PeripheralUpdateCode:
		{
			PeripheralCodeUpdate codeUpdate(recvBuffer);

			if (traceOn)
			{
				HobString msgDebug2 = msgDebug;
				msgDebug2.append("Response from version manager PeripheralUpdateCode:  responseStateMachine_ = ").append(Integer::toString(responseStateMachine_));
				Debug::trace("UsbWrapperCodeUpdater", msgDebug2);
			}

			switch(responseStateMachine_)
			{
				case waitingForResponses:	//waiting for version mrg code update for nodes 1-6 
				{
					if (traceOn)
					{
						HobString msgDebug2 = msgDebug;
						msgDebug2.append("WaitingForResponses:  Total received responses so far = ").append(Integer::toString(responseCounter_));
						Debug::trace("UsbWrapperCodeUpdater", msgDebug2);
					}

					upgradeList_.appendUpgradeVersions(codeUpdate.getCurrentSoftwareVersion(), codeUpdate.getComplexVersion());
					if (codeUpdate.getNodeId() == usbNodeId_)
					{
						responseCounter_--;

						//is upgrade available?
						switch (codeUpdate.getResponseType())
						{
							case SoftwareSystem::AvailableUpgrade:
							{
								if (traceOn)
									Debug::trace("UsbWrapperCodeUpdater", msgDebug + "SoftwareSystem::AvailableUpgrade");

								bool addToBurnList = false, validSW = false;
								UINT16 swMajorRev = 0, swMinorRev = 0;

								HobVersion::VersionType tmpType = codeUpdate.getVersionType();
								HobComplexVersion * pSoftVer = codeUpdate.getComplexVersion();

								if (pSoftVer)
								{
									swMajorRev = pSoftVer->getMajorRevision();
									swMinorRev = pSoftVer->getMinorRevision();
								}

								if (traceOn)
								{
									HobString msgDebug2 = msgDebug;
#if defined ( __linux__ )
									msgDebug2.append("Ready to flash new software for nodeId: ").append(Integer::toString64((int64_t)codeUpdate.getNodeId()));
#else
									msgDebug2.append("Ready to flash new software for nodeId: ").append(Integer::toString64((__int64)codeUpdate.getNodeId()));
#endif
									msgDebug2.append("	type = ").append(Integer::toString(tmpType));
									msgDebug2.append("	swMajorRev = ").append(Integer::toString(swMajorRev));
									msgDebug2.append("	swMinorRev = ").append(Integer::toString(swMinorRev));
									Debug::trace("UsbWrapperCodeUpdater", msgDebug2);
								}

								switch (tmpType)
								{
									case HobVersion::WRMasterNVDataSW:
									case HobVersion::WREMasterNVDataSW:
									case HobVersion::WRMasterBootSW:
									case HobVersion::WREMasterBootSW:
									case HobVersion::WRMasterAppSW:
									case HobVersion::WREMasterAppSW:
									case HobVersion::CLAAppSW:
									case HobVersion::CLADataSW:
									case HobVersion::CLABootSW:
										{																			
											validSW = true;
										}
										break;
									case HobVersion::WRSlave1NVDataSW:
									case HobVersion::WRESlave1NVDataSW:												
									case HobVersion::WRSlave1BootSW:
									case HobVersion::WRESlave1BootSW:
									case HobVersion::WRSlave1AppSW:
									case HobVersion::WRESlave1AppSW:
										{															
											validSW = true;
										}
										break;
									case HobVersion::WRSlave3NVDataSW:
									case HobVersion::WRESlave3NVDataSW:
									case HobVersion::WRSlave3BootSW:
									case HobVersion::WRESlave3BootSW:
									case HobVersion::WRSlave3AppSW:
									case HobVersion::WRESlave3AppSW:
										{																	
											validSW = true;
										}
										break;
									case HobVersion::WRSlave4NVDataSW:
									case HobVersion::WRESlave4NVDataSW:
									case HobVersion::WRSlave4BootSW:
									case HobVersion::WRESlave4BootSW:
									case HobVersion::WRSlave4AppSW:
									case HobVersion::WRESlave4AppSW:
										{																	
											validSW = true;
										}
										break;
									case HobVersion::WRSlave5NVDataSW:
									case HobVersion::WRESlave5NVDataSW:
									case HobVersion::WRSlave5BootSW:
									case HobVersion::WRESlave5BootSW:
									case HobVersion::WRSlave5AppSW:
									case HobVersion::WRESlave5AppSW:
										{																			
											validSW = true;
										}
										break;
									case HobVersion::WRSlave6NVDataSW:
									case HobVersion::WRSlave6BootSW:
									case HobVersion::WRSlave6AppSW:
										{											
											validSW = true;
										}
										break;
									default:
										break;
								}

								if (validSW)
								{
									Debug::trace("UsbWrapperCodeUpdater", HobString("adding to burn list"));
									addToBurnList = true;
								}

								if (addToBurnList)
								{
									Debug::trace("UsbWrapperCodeUpdater", HobString("adding the software to the burn list") );

									util_filesystem::Directory *srcDir = codeUpdate.getPath();
									util_filesystem::File sourceFile(srcDir->getFullPath(), "source.bin");

									if (sourceFile.exists() == true)
									{
										Debug::trace("UsbWrapperCodeUpdater", HobString("source file exists path = ") + sourceFile.getFullPath() );
										//  Add it to the burn list. We will copy and extract the tar file when we need it.
										burnList_.insert(make_pair(tmpType, sourceFile.getFullPath()));
									}
									else
									{
										Debug::trace("UsbWrapperCodeUpdater", HobString("source file doesnt exist path = ") + sourceFile.getFullPath() );
									}
								}
								break;
							}
							case SoftwareSystem::NotAvailable:
							{
								Debug::trace("UsbWrapperCodeUpdater", HobString("SoftwareSystem::NotAvailable: Code not available on internal cf") );
								break;
							}
							case SoftwareSystem::AvailableSameVersion:
							{
								Debug::trace("UsbWrapperCodeUpdater", HobString("SoftwareSystem::AvailableSameVersion") );
								break;
							}
							case SoftwareSystem::retryCntrOver:
							{
								Debug::trace("UsbWrapperCodeUpdater", HobString("SoftwareSystem::retryCntrOver: Failure counter over limit") );
							}
							default:
							{
								Debug::trace("UsbWrapperCodeUpdater", HobString("default: Probably invalid hardware version") );
								break;
							}
						}
					}

					//we have all expected responses.
					if ((responseCounter_ <= 0) && (responseStateMachine_ == waitingForResponses))
					{
						Debug::trace("UsbWrapperCodeUpdater", HobString("Received all responses.") );

						//do we have anything to update?
						if (burnList_.size() > 0)
						{
							Debug::trace("UsbWrapperCodeUpdater", HobString("There is something to burn. Start the burn process.") );

							//  Transition to the Wrapper Upgrade page.
							UpgradePeripheral msg(InitiateUpgradeProcess, Wrapper, WrEvolWrapper);
							dispatchEvent(&msg);

							PAL_absclass::PAL_sleep(1 * 1 * 1000);		//wait for 5 seconds before sending the wrapper upgrade list.

							//update wrapper upgrade page with upgrade list!
							dispatchEvent(&upgradeList_);
							Debug::trace("UsbWrapperCodeUpdater", HobString("upgradeList_ dispatched."));
						}
						else
						{
							//burn list is empty!
							Debug::trace("UsbWrapperCodeUpdater", HobString("Nothing to install, so just wait for a firmware upgrade.") );

							//tell the wrapper to reboot
							pMyWrapperComm_->rebootPeripheral();

							responseStateMachine_ = waitingForNewInstalledSrc;
						}
						//if any requests on the list, free.
						while(reqUpgradeList_.empty() != true)
						{
							PeripheralRequestCodeUpdate *pReqPrnCodeUpdate = reqUpgradeList_.front();								
							reqUpgradeList_.pop_front();

							delete pReqPrnCodeUpdate;
						}
					}
				}		
				break;
				case waitingForNewInstalledSrc:
				{
					Debug::trace("UsbWrapperCodeUpdater", HobString("waitingForNewInstalledSrc: checking for newly installed SW") );																	

					if (codeUpdate.getNodeId() == usbNodeId_)
					{
						Debug::trace("UsbWrapperCodeUpdater", HobString("waitingForNewInstalledSrc, message destined for the wrapper") );																		
						if (codeUpdate.getResponseType() == SoftwareSystem::AvailableUpgrade)
						{
							//we got the first message for firmware upgrade of the wrapper.
							//ignore all other messages if any
							responseStateMachine_ = waitingForComponentCheckComplete;
						}
					}
				} 
				break;
				default:
				{
					Debug::trace("UsbWrapperCodeUpdater", HobString("default: ignoring PeripheralCodeUpdate message because of current state") );																		
				}
				break;
			} 
			break;
		}
		case CancelUpgrade:
		{
			Debug::trace("UsbWrapperCodeUpdater", msgDebug + "CancelUpgrade:  Will not upgrade the wrapper. See if they want to remove the TAR files.");
			VmStatusMsg status(NULL, VMUSBWrapperRequestRemoveWrapperTarFiles, HfcResponse::RESPONSESTYLE_OKCANCEL, false);
			dispatchEvent(&status); 

			//tell the wrapper to reboot
			pMyWrapperComm_->rebootPeripheral();
			break;
		}
		case BeginUpgrade:
		{
			HobString msgDebug2;
			if (traceOn)
			{
				msgDebug2 = msgDebug;
				msgDebug2.append("BeginUpgrade:  ");
				Debug::trace("UsbWrapperCodeUpdater", msgDebug2 + "Starting to upgrade the wrapper.");
			}

			if (pMyWrapperComm_)
			{
				if (traceOn)
					Debug::trace("UsbWrapperCodeUpdater", msgDebug2 + "Creating comm manager.");

				pMyWrapperComm_->createCommLink(); 

				//  Notify the WrapperManager that we are now Upgrading the Wrapper.
				WrapperGeneric msg((WrEvent) WrEvolUpgradeInProgress, this);
				dispatchEvent(&msg);

				if (traceOn)
					Debug::trace("UsbWrapperCodeUpdater", msgDebug2 + "Calling setupCodeFlash() in 5 seconds.");

				//  Wait for 5 seconds.
				PAL_absclass::PAL_sleep(1 * 5 * 1000);						

				//send the burn list to the wrapper!!!!
				pMyWrapperComm_->setupCodeFlash(burnList_);

				responseStateMachine_ = sendingOutCommand;

				if (traceOn)
					Debug::trace("UsbWrapperCodeUpdater", msgDebug2 + "responseStateMachine_ = sendingOutCommand (" + Integer::toString(responseStateMachine_) + ")");
			}
			else
			{
				if (traceOn)
					Debug::trace("UsbWrapperCodeUpdater", msgDebug2 + "Failed to create code updater object.");

				responseStateMachine_ = waitingForNewInstalledSrc;

				if (traceOn)
					Debug::trace("UsbWrapperCodeUpdater", msgDebug2 + "responseStateMachine_ = waitingForNewInstalledSrc (" + Integer::toString(responseStateMachine_) + ")");
			}
			break;
		}
		case ComponentCheckComplete:
		{
			Debug::trace("UsbWrapperCodeUpdater", msgDebug + "ComponentCheckComplete:  Sending WrapperSystemRequestStatus.");

			responseStateMachine_ = waitingForNewInstalledSrc;

			WrapperSystemRequestStatus wsrs(this);
			const char *pCC = wsrs.serialize();
			pMyWrapperComm_->send(pCC, wsrs.getSerializedLength());
			break;
		}

		default:
			Debug::trace("UsbWrapperCodeUpdater", HobString("default case - we are not handling this."));
			break;
	}
}

void UsbWrapperCodeUpdater::shutdownTimeout(void *pObject)
{
	UsbWrapperCodeUpdater *pUpdater = (UsbWrapperCodeUpdater *)pObject;

	PAL_absclass::PAL_sleep(1 * 60 * 1000);		//wait for 1 min.

	WrapperSystemRequestStatus wsrs(pUpdater);
	wsrs.setSourceObject(pUpdater);

	Debug::trace("UsbWrapperCodeUpdater", HobString("shutdownTimeout():  sending WrapperSystemRequestStatus."));
	const char *pCC = wsrs.serialize();
	pUpdater->pMyWrapperComm_->send(pCC, wsrs.getSerializedLength());
}

bool UsbWrapperCodeUpdater::isUpdateComplete()
{
	bool updateComplete = false;

	if (pMyWrapperComm_)
		updateComplete = pMyWrapperComm_->areTransactionsComplete();

	Debug::trace("UsbWrapperCodeUpdater", "isUpdateComplete() == " + HobString(Bool::toString(updateComplete)));
	return updateComplete;
}
